SELECT sno, sname FROM student
  WHERE sdept = '计算机'
    AND sage BETWEEN 19 AND 20;
SELECT * FROM student
  WHERE sname LIKE '张%' OR sname LIKE '李%';
SELECT sname, YEAR(CURDATE()) - sage AS 出生年份
  FROM student
  ORDER BY sage DESC;
SELECT sname, sage FROM student
  ORDER BY sage DESC LIMIT 2;

