SELECT sno FROM sc
WHERE AVG(grade) > 80
GROUP BY sno;

questions.answer:
SELECT cno, COUNT(*) AS 人数,
       MAX(grade) AS 最高分,
       MIN(grade) AS 最低分,
       ROUND(AVG(grade), 1) AS 平均分
  FROM sc GROUP BY cno;
SELECT sno, COUNT(*) AS 门数 FROM sc
  GROUP BY sno HAVING COUNT(*) >= 2
  ORDER BY 门数 DESC;
SELECT sno, AVG(grade) AS 平均成绩 FROM sc
  GROUP BY sno HAVING AVG(grade) > 85;
SELECT cno, COUNT(*) AS 不及格人数 FROM sc
  WHERE grade < 60 GROUP BY cno;
